package com.campusmart.service;
import com.campusmart.entity.*;import com.campusmart.repository.*;import com.campusmart.dto.OrderDtos;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service public class OrderService{private final OrderRepository orders;private final ProductRepository products;private final CartItemRepository carts;private final UserService users;public OrderService(OrderRepository o,ProductRepository p,CartItemRepository c,UserService u){orders=o;products=p;carts=c;users=u;}public Order create(OrderDtos.Create d,Long uid){User buyer=users.get(uid);Order o=new Order();o.setBuyer(buyer);BigDecimal total=BigDecimal.ZERO;for(var i:d.items()){Product p=products.findById(i.productId()).orElseThrow(()->new IllegalArgumentException("Product not found: "+i.productId()));if(!p.isAvailable())throw new IllegalArgumentException(p.getName()+" is unavailable");if(i.quantity()<1)throw new IllegalArgumentException("Quantity must be at least 1");BigDecimal line=p.getPrice().multiply(BigDecimal.valueOf(i.quantity()));total=total.add(line);OrderItem oi=new OrderItem();oi.setOrder(o);oi.setProduct(p);oi.setQuantity(i.quantity());oi.setUnitPrice(p.getPrice());o.getItems().add(oi);p.setAvailable(false);products.save(p);}o.setTotal(total);Order saved=orders.save(o);carts.deleteByUserId(uid);return saved;}public List<Order>mine(Long uid){return orders.findByBuyerIdOrderByCreatedAtDesc(uid);}public Order get(Long id){return orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));}public void status(Long id,Order.Status status){Order o=get(id);o.setStatus(status);orders.save(o);}}
